            2'b00: burst_len = 4'd1;   // Fixed
            2'b01: burst_len = 4'd4;   // INCR4
            2'b10: burst_len = 4'd8;   // INCR8
            2'b11: begin               // WRAP
                burst_len  = 4'd4;
                burst_wrap = 1'b1;
            end
            default: ;
        endcase
    end

