module cpu_full_decoder (
    input  logic [31:0] instr,
    output logic        reg_write,
    output logic        mem_read,
    output logic        mem_write,
    output logic        branch,
    output logic        illegal
);

    logic [6:0] opcode;
    logic [2:0] funct3;
    logic [1:0] addr_mode;

    assign opcode    = instr[6:0];
    assign funct3    = instr[14:12];
    assign addr_mode = instr[21:20];

    always_comb begin
        reg_write = 1'b0;
        mem_read  = 1'b0;
        mem_write = 1'b0;
        branch    = 1'b0;
        illegal   = 1'b0;

        unique case (opcode)

            7'b0110011: begin // ALU register ops
                reg_write = 1'b1;
                unique case (funct3)
                    3'b000, 3'b111, 3'b110: ; // ADD/AND/OR
                    default: illegal = 1'b1;
                endcase
            end

            7'b0000011: begin // LOAD
                mem_read  = 1'b1;
                reg_write = 1'b1;
                unique case (funct3)
                    3'b010: begin // LW
                        case (addr_mode)
                            2'b00, 2'b01: ; // direct/indexed
                            2'b10: illegal = 1'b1;
                            default: illegal = 1'b1;
                        endcase
                    end
                    default: illegal = 1'b1;
                endcase
            end

            7'b0100011: begin // STORE
                mem_write = 1'b1;
                unique case (funct3)
                    3'b010: begin // SW
                        case (addr_mode)
                            2'b00: ;        // direct
                            2'b01: ;        // indexed
                            default: illegal = 1'b1;
                        endcase
                    end
                    default: illegal = 1'b1;
                endcase
            end

            7'b1100011: begin // BRANCH
                branch = 1'b1;
                unique case (funct3)
                    3'b000, 3'b001: ; // BEQ/BNE
                    default: illegal = 1'b1;
                endcase
            end

            default: illegal = 1'b1;
        endcase
    end

endmodule,"

module interconnect_router (
