                            default: route_slow = 1'b1;
                        endcase
                    end
                    default: reject = 1'b1;
                endcase
            end

            4'hF: begin
                case (txn_type)
                    2'b00: route_slow = 1'b1;
                    default: reject = 1'b1;
                endcase
            end

            default: reject = 1'b1;
        endcase
    end

