module lifecycle_gate (
    input  logic [2:0] lc_state,
    input  logic [1:0] transition,
    output logic       allow,
    output logic       violation
);

    always_comb begin
        allow     = 1'b0;
        violation = 1'b0;

        unique case (lc_state)
            3'b000: begin // TEST_UNLOCKED
                case (transition)
                    2'b00, 2'b01: allow = 1'b1;
                    default: violation = 1'b1;
                endcase
            end

            3'b001: begin // DEV
                case (transition)
                    2'b01: allow = 1'b1;
                    default: violation = 1'b1;
