            3'b010: begin // PROD
                case (transition)
                    2'b10: allow = 1'b1;
                    default: violation = 1'b1;
                endcase
            end

            3'b111: begin // RMA
                case (transition)
                    2'b11: allow = 1'b1;
                    default: violation = 1'b1;
                endcase
            end

            default: violation = 1'b1;
        endcase
    end

