                            default: stall_o[i] = 1'b1;
                        endcase
                    end
                    2'b01: begin
                        unique case (lru_i[i])
                            2'b00: grant_o[i] = 1'b1;
                            2'b01: evict_o[i] = 1'b1;
                            default: stall_o[i] = 1'b1;
                        endcase
                    end
                    2'b10: begin
                        unique case (lru_i[i])
                            2'b00, 2'b01: grant_o[i] = 1'b1;
                            2'b10: evict_o[i] = 1'b1;
