module tl_axi_obi_sec (
    input  logic tl_valid_i,
    input  logic [2:0] tl_opcode_i,
    input  logic axi_awvalid_i,
    input  logic axi_arvalid_i,
    input  logic [1:0] obi_resp_i,
    input  logic priv_i,
    output logic tl_a_valid_o,
    output logic [2:0] tl_a_opcode_o,
    output logic obi_req_o,
    output logic obi_we_o,
    output logic [1:0] axi_rresp_o
);

    always_comb begin
        tl_a_valid_o  = 1'b0;
        tl_a_opcode_o = 3'b000;
        obi_req_o     = 1'b0;
        obi_we_o      = 1'b0;
        axi_rresp_o   = 2'b00;

        if (tl_valid_i) begin
            unique case (tl_opcode_i)
                3'b000: begin
                    tl_a_valid_o  = 1'b1;
                    tl_a_opcode_o = 3'b000;
                    obi_req_o     = 1'b1;
                    obi_we_o      = 1'b0;
                end
                3'b001, 3'b010: begin
                    tl_a_valid_o  = 1'b1;
                    tl_a_opcode_o = tl_opcode_i;
                    obi_req_o     = 1'b1;
                    obi_we_o      = 1'b1;
                end
                default: axi_rresp_o = 2'b11;
            endcase
        end

        unique case (1'b1)
            axi_arvalid_i: begin
                tl_a_valid_o  = 1'b1;
                tl_a_opcode_o = 3'b000;
            end
            axi_awvalid_i: begin
                tl_a_valid_o  = 1'b1;
                tl_a_opcode_o = 3'b001;
            end
        endcase

        unique case (obi_resp_i)
            2'b00: axi_rresp_o = 2'b00;
            2'b10: axi_rresp_o = 2'b10;
            default: axi_rresp_o = 2'b11;
        endcase

        if (!priv_i) begin
            tl_a_valid_o = 1'b0;
            obi_req_o    = 1'b0;
            axi_rresp_o  = 2'b10;
        end
    end
endmodule,,INVALID_OUTPUT,0.5545487403869629,0,0

module chisel_event_fsm_alert (
    input  logic [7:0] evt_i,
    input  logic [3:0] state_i,
    input  logic alert_i,
    output logic fire_o,
    output logic stall_o,
    output logic error_o
);

    always_comb begin
        fire_o  = 1'b0;
        stall_o = 1'b0;
        error_o = 1'b0;

        unique case (state_i)
            4'd0: unique case (evt_i[1:0])
                      2'b00: fire_o = alert_i ? 1'b0 : 1'b1;
                      2'b01: stall_o = 1'b1;
                      default: error_o = 1'b1;
                  endcase
            4'd1: unique case (evt_i[3:2])
                      2'b00: fire_o = alert_i ? 1'b0 : 1'b1;
                      2'b01: stall_o = 1'b1;
                      default: error_o = 1'b1;
                  endcase
            4'd2: unique case (evt_i[5:4])
                      2'b00: fire_o = alert_i ? 1'b0 : 1'b1;
                      2'b01: stall_o = 1'b1;
                      default: error_o = 1'b1;
                  endcase
            4'd3: unique case (evt_i[7:6])
                      2'b00: fire_o = alert_i ? 1'b0 : 1'b1;
                      2'b01: stall_o = 1'b1;
                      default: error_o = 1'b1;
                  endcase
            default: error_o = 1'b1;
        endcase
    end
endmodule,"

module piton_l2_repl_priv (
    input  logic [3:0] req_i,
    input  logic [1:0] line_state_i [3:0],
    input  logic [1:0] lru_i [3:0],
    input  logic priv_i [3:0],
    output logic [3:0] grant_o,
    output logic [3:0] evict_o,
    output logic [3:0] stall_o
);

    always_comb begin
        grant_o = 4'b0000;
        evict_o = 4'b0000;
        stall_o = 4'b0000;

        for (int i = 0; i < 4; i++) begin
            if (req_i[i]) begin
                unique case (line_state_i[i])
                    2'b00: grant_o[i] = priv_i[i];
                    2'b01: unique case (lru_i[i])
                                2'b00: grant_o[i] = 1'b1;
                                2'b01: evict_o[i] = 1'b1;
                                default: stall_o[i] = 1'b1;
                            endcase
                    2'b10: evict_o[i] = 1'b1;
                    2'b11: stall_o[i] = 1'b1;
                    default: stall_o[i] = 1'b1;
                endcase
            end
        end
    end
endmodule,"

module axi_tl_bridge_fsm (
    input  logic axi_awvalid_i,
    input  logic axi_arvalid_i,
    input  logic tl_ready_i,
    input  logic [2:0] tl_opcode_i,
    output logic tl_valid_o,
    output logic [2:0] tl_a_opcode_o,
    output logic error_o
);

    always_comb begin
        tl_valid_o = 1'b0;
        tl_a_opcode_o = 3'b000;
        error_o = 1'b0;

        if (axi_awvalid_i) begin
            tl_valid_o = tl_ready_i;
            tl_a_opcode_o = 3'b001;
        end else if (axi_arvalid_i) begin
            tl_valid_o = tl_ready_i;
            tl_a_opcode_o = 3'b000;
        end else begin
            error_o = 1'b1;
        end
    end
endmodule,"
